mapper.insert:
/* apiTmplt.savTmplt */

  SELECT CURRVAL('koa_tb_api_quick_tmplt_tmplt_no_seq')

INSERT INTO KOA_TB_API_QUICK_TMPLT
(
   TMPLT_NM
  ,TMPLT_DESC
  ,API_CLASS
  ,MTH_TYPE_CD
  ,CNT_TYPE_CD
  ,PATH_PATTERN
  ,DFLT_PARAM_JSON
  ,DFLT_FIELD_JSON
  ,TMPLT_YAML
  ,SORT_ODRG
  ,USE_YN
  ,REG_DT
  ,REGR
)
VALUES
(
   #{tmpltNm}
  ,#{tmpltDesc}
  ,#{apiClass}
  ,#{mthTypeCd}
  ,NULLIF(#{cntTypeCd}, '')
  ,#{pathPattern}
  ,#{dfltParamJson}
  ,#{dfltFieldJson}
  ,#{tmpltYaml}
  ,COALESCE((SELECT MAX(SORT_ODRG) + 1 FROM KOA_TB_API_QUICK_TMPLT), 1)
  ,'Y'
  ,NOW()
  ,#{regr}
)

mapper.update:
/* apiTmplt.updTmplt */
UPDATE KOA_TB_API_QUICK_TMPLT
SET
   TMPLT_NM        = #{tmpltNm}
  ,TMPLT_DESC      = #{tmpltDesc}
  ,API_CLASS       = #{apiClass}
  ,MTH_TYPE_CD     = #{mthTypeCd}
  ,CNT_TYPE_CD     = NULLIF(#{cntTypeCd}, '')
  ,PATH_PATTERN    = #{pathPattern}
  ,DFLT_PARAM_JSON = #{dfltParamJson}
  ,DFLT_FIELD_JSON = #{dfltFieldJson}
  ,TMPLT_YAML      = #{tmpltYaml}
  ,AMD_DT          = NOW()
  ,AMDR            = #{amdr}
WHERE TMPLT_NO = #{tmpltNo}::integer
